        "matcher": "Write|Edit",
        "command": "LINE_COUNT=$(wc -l < \"$FILE_PATH\" 2>/dev/null || echo 0); [ \"$LINE_COUNT\" -gt 500 ] && echo \"⚠️  WARNING: $FILE_PATH has $LINE_COUNT lines (>500). Consider splitting.\" >&2; exit 0",
        "description": "Warn if file exceeds 500 lines"
