      {
        "matcher": "Write|Edit",
        "command": "case \"$FILE_PATH\" in */tests/*.py) PYTHONPATH=./docs_src pytest -x \"$FILE_PATH\" ;; esac",
        "description": "Run modified test file with PYTHONPATH set for docs_src imports"
